const items = $input.all();
if (!items || items.length === 0) {
  const wanted = $('Config').first().json['Topic Title'];
  throw new Error(`No topic found titled "${wanted}". It must exactly match a topic already created in Phase 1.`);
}
const topic = items[0].json;
return [{ json: { topic_id: topic.id, topic_title: topic.title, channel_id: topic.channel_id } }];

const items = $input.all();
if (!items || items.length === 0) {
  throw new Error('No research dossier found for this topic. Run Phase 1 (phase1-topic-entry-research.json) for this topic first.');
}
const dossier = items[0].json;
const claims = Array.isArray(dossier.claims) ? dossier.claims : [];
const usableClaims = claims.filter(c => c.status === 'verified' || c.status === 'conflicting');
if (usableClaims.length === 0) {
  throw new Error('This dossier has no verified or conflicting claims to build a script from — it needs more research first.');
}
return [{ json: { dossier_id: dossier.id, usable_claims: usableClaims } }];

const items = $input.all();
if (!items || items.length === 0) {
  throw new Error('Channel not found for this topic — data inconsistency, check the topics/channels tables.');
}
const channel = items[0].json;
return [{ json: { brand_voice: channel.brand_voice, niche: channel.niche } }];

function fnv1a(str) {
  let h = 0x811c9dc5;
  for (let i = 0; i < str.length; i++) {
    h ^= str.charCodeAt(i);
    h = Math.imul(h, 0x01000193);
  }
  return (h >>> 0).toString(16).padStart(8, '0');
}

const claims = $('Pick Dossier Row').first().json.usable_claims;
const minutes = $('Config').first().json['Target Runtime Minutes'];
const dossierText = JSON.stringify(claims, null, 2);

const system = `You are the Story Architect. You do not write narration — you build the structural
arc a script will follow.

Dossier: ${dossierText}
Target runtime: ${minutes} minutes

Build an outline with these beats:
- HOOK: the single most surprising or tension-creating fact from the dossier, framed
  as a question or incomplete thought
- PROBLEM: what's actually at stake or unresolved
- CONTEXT: the minimum background a viewer needs, no more
- ESCALATION: how the situation or stakes build
- SURPRISE: the turn — something the viewer didn't expect, grounded in a verified claim
- EXPLANATION: the payoff — how/why, using the dossier's strongest verified material
- PAYOFF: what this means, why it matters, or what happens next

Allocate approximate seconds per beat. Every beat must cite which dossier claim(s) it
uses — if a beat has no dossier support, cut it or flag it for more research.

Respond with JSON only, no prose outside the JSON, matching exactly this shape:
{
  "beats": [
    { "beat": "HOOK" | "PROBLEM" | "CONTEXT" | "ESCALATION" | "SURPRISE" | "EXPLANATION" | "PAYOFF", "seconds": number, "summary": string, "cited_claims": [string] }
  ]
}`;

return [{ json: { system, input_hash: fnv1a(system) } }];

const raw = $input.first().json["Claude's outline JSON"] || '';
let parsed = null;
let parseError = null;
try {
  const match = raw.match(/\{[\s\S]*\}/);
  parsed = JSON.parse(match ? match[0] : raw);
} catch (e) {
  parseError = e.message;
}
if (parseError || !Array.isArray(parsed?.beats) || parsed.beats.length === 0) {
  throw new Error('Could not parse a valid outline JSON (needs a non-empty "beats" array). Paste error: ' + (parseError || 'no beats array found'));
}
return [{ json: { beats: parsed.beats, raw_text: raw } }];

