}

const brandVoice = $('Pick Channel Info Row').first().json.brand_voice;
const outline = $('Parse Outline JSON').first().json.beats;
const outlineText = JSON.stringify(outline, null, 2);

const system = `You are the Script Writer. Turn the story outline into narration written for
voiceover — no on-camera presence, no visual-dependent phrasing like "as you can see
here" unless a shot is specifically planned for that moment.

Voice: ${brandVoice}
Outline: ${outlineText}

Rules:
- Sentences built for the ear, not the eye — shorter and more rhythmic than page prose.
- No filler transitions ("moving on", "so anyway"). Cut straight into the next beat.
- Every factual statement must match a dossier claim — don't round up, don't add
  color that isn't sourced.
- Vary sentence length deliberately — short for emphasis and impact, longer for
  context and explanation.

Output the full script labeled [HOOK] [PROBLEM] [CONTEXT] [ESCALATION] [SURPRISE]
[EXPLANATION] [PAYOFF], with estimated word count and runtime per section
(150 words ~= 60 seconds at natural pace). Plain text, not JSON.`;

return [{ json: { system, input_hash: fnv1a(system) } }];

function fnv1a(str) {
  let h = 0x811c9dc5;
  for (let i = 0; i < str.length; i++) {
    h ^= str.charCodeAt(i);
    h = Math.imul(h, 0x01000193);
  }
  return (h >>> 0).toString(16).padStart(8, '0');
}

const script = $('Paste Script Writer Response').first().json["Claude's script text"];

const system = `You are the Script Critic. You did not write this script — attack it.

Script: ${script}

Answer directly, don't soften:
1. Where would a viewer actually leave? Name the timestamp/section.
2. What's boring? What could be cut entirely with no loss?
3. Is the hook (first ~15 seconds) strong enough to survive the algorithm's
   swipe-away window? If not, why not?
4. Any claim that reads like it's not actually backed by the dossier, even if
   technically sourced — does it feel like padding or an unsupported leap?
5. Does the payoff actually pay off, or does it fizzle?

Score 1-10 on hook strength, pacing, and payoff satisfaction. A script under 7 on
any dimension goes back to the writer with your specific notes — exact lines and
what's wrong with them, not general feedback like "make it better."

Respond with JSON only, no prose outside the JSON, matching exactly this shape:
{
  "hook_score": number,
  "pacing_score": number,
  "payoff_score": number,
  "weak_points": [ { "timestamp_or_section": string, "issue": string } ],
  "notes": string
}`;

return [{ json: { system, input_hash: fnv1a(system) } }];

function fnv1a(str) {
  let h = 0x811c9dc5;
  for (let i = 0; i < str.length; i++) {
    h ^= str.charCodeAt(i);
    h = Math.imul(h, 0x01000193);
  }
  return (h >>> 0).toString(16).padStart(8, '0');
}

const raw = $input.first().json["Claude's critique JSON"] || '';
let parsed = null;
let parseError = null;
try {
  const match = raw.match(/\{[\s\S]*\}/);
  parsed = JSON.parse(match ? match[0] : raw);
} catch (e) {
  parseError = e.message;
}
if (parseError) {
  throw new Error('Could not parse the critique JSON: ' + parseError);
}

const hook = Number(parsed.hook_score);
const pacing = Number(parsed.pacing_score);
const payoff = Number(parsed.payoff_score);
const pass = hook >= 7 && pacing >= 7 && payoff >= 7;

return [{ json: {
  hook_score: hook,
  pacing_score: pacing,
  payoff_score: payoff,
  weak_points: parsed.weak_points || [],
  notes: parsed.notes || '',
  pass,
  raw_text: raw,
  output_hash: fnv1a(raw)
} }];

const critic = $('Parse Critic JSON').first().json;
return [{ json: {
  result: 'PASSED — script is final, video row created for Phase 3',
  topic: $('Pick Topic Row').first().json.topic_title,
  hook_score: critic.hook_score,
  pacing_score: critic.pacing_score,
  payoff_score: critic.payoff_score,
  video_id: $('Insert Video Row').first().json.id,
  script_id: $('Pick Final Script Row').first().json.script_id
} }];

const critic = $('Parse Critic JSON').first().json;
return [{ json: {
  result: 'NEEDS REWORK — no video row created. Revise the script using the notes below (by hand, or by re-running the Script Writer prompt in your own Claude chat with these notes appended), then re-submit this form to try again.',
  topic: $('Pick Topic Row').first().json.topic_title,
  hook_score: critic.hook_score,
  pacing_score: critic.pacing_score,
  payoff_score: critic.payoff_score,
  weak_points: critic.weak_points,
  notes: critic.notes
} }];
